 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    from collections import Counter
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    # Find uniform separator lines and repeat colored pattern across equal-sized blocks.
    for axis,n,m in ((0,h,w),(1,w,h)):
        seps=[]
        for i in range(n):
            vals=[g[i][j] for j in range(m)] if axis==0 else [g[j][i] for j in range(m)]
            if len(set(vals))==1 and vals[0]!=bg: seps.append((i,vals[0]))
        if not seps: continue
        # Repeated full lines identify the period; otherwise use the first line as a divider.
        if len(seps)>=2:
            period=seps[1][0]-seps[0][0]
            if period<=0: continue
            for residue in range(period):
                values={}
                for i in range(n):
                    if i not in [x for x,_ in seps] and i%period==residue:
                        for j in range(m):
                            v=g[i][j] if axis==0 else g[j][i]
                            if v!=bg: values[j]=v
                for i in range(n):
                    if i%period==residue and i not in [x for x,_ in seps]:
                        for j,v in values.items():
                            if axis==0: g[i][j]=v
                            else: g[j][i]=v
            return g
        # Single horizontal/vertical divider: clone the motif immediately above/left below/right.
        sep=seps[0][0]
        block=sep if axis==0 else sep
        if block==0: continue
        for i in range(sep+1,n):
            src=(i-sep-1)%block
            src=src if axis==0 else src
            for j in range(m):
                v=g[src][j] if axis==0 else g[j][src]
                if v!=bg:
                    if axis==0: g[i][j]=v
                    else: g[j][i]=v
        return g
    return g
